#include "gba/genres/RoguelikeModule.h"
#include "gba/genres/GenreUtil.h"
#include <algorithm>
#include <cmath>
#include <sstream>

namespace gba { using namespace genreutil;
std::string RoguelikeModule::genre()const{return "roguelike";}
std::vector<ParameterSpec>RoguelikeModule::balanceParameters(const GameDefinition&g)const{std::vector<ParameterSpec>p;for(const auto&i:arrayObjects(g.raw,"items")){auto id=str(i,"id");p.push_back(spec("item."+id+".powerMul",1,.45,2.5,.18));p.push_back(spec("item."+id+".priceMul",1,.5,2,.16));p.push_back(spec("item."+id+".dropMul",1,.35,2.5,.2));}for(const auto&e:arrayObjects(g.raw,"enemies")){auto id=str(e,"id");p.push_back(spec("enemy."+id+".hpMul",1,.5,2.4,.18));p.push_back(spec("enemy."+id+".damageMul",1,.5,2.3,.18));p.push_back(spec("enemy."+id+".rewardMul",1,.55,1.8,.14));}p.push_back(spec("healingMul",1,.5,1.8,.15));p.push_back(spec("difficultyGrowth",1,.65,1.55,.14));return p;}
std::vector<ParameterSpec>RoguelikeModule::strategyParameters(const GameDefinition&g)const{std::vector<ParameterSpec>p;for(const auto&i:arrayObjects(g.raw,"items"))p.push_back(spec("pref."+str(i,"id"),1,.02,4,.22));p.push_back(spec("risk",.8,.1,1.8,.18));p.push_back(spec("healBias",.8,.1,2,.18));p.push_back(spec("shopBias",.8,.1,2,.18));return p;}
SimulationResult RoguelikeModule::simulate(const GameDefinition&g,const Genome&b,const Genome&s,std::uint64_t seed,int maxP)const{std::mt19937_64 rng(seed);SimulationResult r;r.strategyId=s.id;r.balanceId=b.id;r.seed=seed;auto items=arrayObjects(g.raw,"items"),enemies=arrayObjects(g.raw,"enemies");auto rules=g.raw["rules"];double hp=attr(rules,"playerHp",100),startHp=hp,gold=attr(rules,"startGold",15),income=gold,basePower=attr(rules,"basePower",10),defense=attr(rules,"baseDefense",0);double early=hp;std::map<std::string,double>owned;
 for(int room=1;room<=maxP;++room){const Json&e=enemies[static_cast<std::size_t>((room-1)%std::max<int>(1,enemies.size()))];auto eid=str(e,"id","enemy");double growth=gene(b,"difficultyGrowth");double ehp=attr(e,"hp",25)*gene(b,"enemy."+eid+".hpMul")*std::pow(1.03*growth,room);double edmg=attr(e,"damage",5)*gene(b,"enemy."+eid+".damageMul")*(1+.018*room);double power=basePower,armor=defense,utility=0;for(const auto&i:items){auto id=str(i,"id"),role=str(i,"role","damage");double n=owned[id];if(n<=0)continue;double p=attr(i,"power",4)*gene(b,"item."+id+".powerMul")*n;if(role=="defense")armor+=p;else if(role=="utility")utility+=p;else power+=p;r.contribution[id]+=p;}
 double rounds=std::max(1.0,ehp/std::max(1.0,power));double taken=std::max(0.0,edmg-armor*.2)*rounds*.18*(1-.18*std::min(1.5,s.get("risk",.8)));hp-=taken;if(hp<=0){r.progress=room;r.success=false;break;}double reward=attr(e,"reward",8)*gene(b,"enemy."+eid+".rewardMul");gold+=reward;income+=reward;
 if(hp<startHp*.45&&gold>=attr(rules,"healCost",12)&&s.get("healBias",.8)>.5){double cost=attr(rules,"healCost",12);gold-=cost;hp=std::min(startHp,hp+attr(rules,"healAmount",25)*gene(b,"healingMul"));r.usage["heal"]+=1;}
 if(room%2==0&&!items.empty()&&s.get("shopBias",.8)>.25){const Json*best=nullptr;double bu=-1;for(const auto&i:items){auto id=str(i,"id");double price=attr(i,"price",20)*gene(b,"item."+id+".priceMul");if(price>gold)continue;double u=s.get("pref."+id,1)*attr(i,"power",4)/std::max(1.0,price)*(.9+.2*rand01(rng));if(u>bu){bu=u;best=&i;}}if(best){auto id=str(*best,"id");double price=attr(*best,"price",20)*gene(b,"item."+id+".priceMul");gold-=price;owned[id]++;r.usage[id]+=1;}}
 if(rand01(rng)<.12&&!items.empty()){const auto&i=items[static_cast<std::size_t>(rng()%items.size())];auto id=str(i,"id");if(rand01(rng)<std::min(1.0,.35*gene(b,"item."+id+".dropMul"))){owned[id]++;r.usage[id]+=1;}}
 if(room==5) early=hp;
 r.progress=room;
 }
r.success=r.progress>=maxP;r.earlySafety=clamp01(early/startHp);r.resourceIncome=std::max(1.0,income);r.resourceResidual=gold;r.score=r.progress*32+r.earlySafety*500+r.success*1100;return r;}
EvaluationSummary RoguelikeModule::evaluateBalance(const GameDefinition&g,const Genome&b,const std::vector<SimulationResult>&runs)const{auto e=IGameModule::evaluateBalance(g,b,runs);double target=g.raw["targets"]["targetProgress"].asNumber(40);if(e.avgProgress<target*.7)e.fitness-=(target*.7-e.avgProgress)*45;e.fitness-=std::max(0.0,e.topPairShare-.76)*5000;e.fitness+=e.diversity*600;std::ostringstream o;o<<"Rogue target="<<e.fitness<<" rooms="<<e.avgProgress<<" duo="<<e.topPairShare;e.explanation=o.str();return e;}
std::vector<Genome>RoguelikeModule::targetedBalanceExperiments(const GameDefinition&g,const Genome&base,const EvaluationSummary&c,std::uint64_t&nid,int gen,std::mt19937_64&,double strength)const{std::vector<Genome>v;std::string hi,lo;double a=-1,z=1e99;for(const auto&i:arrayObjects(g.raw,"items")){auto id=str(i,"id");double q=c.meanContribution.count(id)?c.meanContribution.at(id):0,u=c.meanUsage.count(id)?c.meanUsage.at(id):0;if(q>a){a=q;hi=id;}if(u<z){z=u;lo=id;}}if(!hi.empty()&&!lo.empty()&&hi!=lo){Genome n=base;n.id=nid++;n.generation=gen;n.note="anti-item-meta:"+hi+"->"+lo;n.genes["item."+hi+".powerMul"]*=1-strength*.3;n.genes["item."+lo+".powerMul"]*=1+strength*.3;n.genes["item."+lo+".priceMul"]*=1-strength*.12;v.push_back(n);}return v;}
}
